import sys

def find_words_brute(board, words):
    m, n = len(board), len(board[0])
    res = []
    for word in words:
        found = False
        for i in range(m):
            for j in range(n):
                if board[i][j] != word[0]:
                    continue
                seen = [[False] * n for _ in range(m)]
                def dfs(x, y, idx):
                    if idx == len(word):
                        return True
                    if x < 0 or x >= m or y < 0 or y >= n or seen[x][y] or board[x][y] != word[idx]:
                        return False
                    seen[x][y] = True
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        if dfs(x + dx, y + dy, idx + 1):
                            return True
                    seen[x][y] = False
                    return False
                if dfs(i, j, 0):
                    found = True
                    break
            if found:
                break
        if found:
            res.append(word)
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m = int(data[0]); n = int(data[1])
    board = []
    idx = 2
    for _ in range(m):
        board.append(data[idx:idx + n])
        idx += n
    wcnt = int(data[idx]); idx += 1
    words = data[idx:idx + wcnt]
    for w in find_words_brute(board, words):
        print(w)

import sys

class Node:
    __slots__ = ('children', 'word')
    def __init__(self):
        self.children = {}
        self.word = None

def find_words_trie(board, words):
    root = Node()
    for w in words:
        cur = root
        for ch in w:
            if ch not in cur.children:
                cur.children[ch] = Node()
            cur = cur.children[ch]
        cur.word = w
    m, n = len(board), len(board[0])
    res = []
    def dfs(x, y, node):
        if node.word:
            res.append(node.word)
            node.word = None
        if x < 0 or x >= m or y < 0 or y >= n or board[x][y] is None:
            return
        ch = board[x][y]
        nxt = node.children.get(ch)
        if not nxt:
            return
        board[x][y] = None
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            dfs(x + dx, y + dy, nxt)
        board[x][y] = ch
    for i in range(m):
        for j in range(n):
            dfs(i, j, root)
    return sorted(res)

if __name__ == '__main__':
